// The Resume page: bullet points per course or project, generated by the
// AI gateway, edited by the student and saved as a draft.
import { apiClient } from "./apiClient";
import type { StudentProfile } from "../career/careerData";

export type BlockKind = "course" | "project";

// One section of the resume as the server returns it.
export interface GeneratedBlock {
  key: string; // "course:12" or "project:3"
  kind: BlockKind;
  refId: number;
  heading: string;
  bullets: string[];
  error?: string;
}

export interface DraftBullet {
  text: string;
  edited: boolean; // the student changed it; only Regenerate replaces it
}

export interface DraftBlock {
  key: string;
  kind: BlockKind;
  refId: number;
  heading: string;
  bullets: DraftBullet[];
}

export interface ResumeDraft {
  blocks: DraftBlock[];
  updatedAt: string | null;
}

export interface BlocksRequest {
  courseIds: number[];
  projectIds: number[];
  careerGoals: string[];
}

export const getResumeOptions = () =>
  apiClient<{ profile: StudentProfile; completedCourseIds: number[] }>("/api/resume/options");

// All new sections at once, or a single one to regenerate it.
export const generateBlocks = (body: BlocksRequest) =>
  apiClient<{ blocks: GeneratedBlock[] }>("/api/resume/blocks", {
    method: "POST",
    body: JSON.stringify(body),
  });

export const getDraft = () => apiClient<ResumeDraft>("/api/resume/draft");

export const saveDraft = (blocks: DraftBlock[]) =>
  apiClient<ResumeDraft>("/api/resume/draft", {
    method: "PUT",
    body: JSON.stringify({ blocks }),
  });
